    $pdo=production_database_connection();$stmt=$pdo->prepare('SELECT * FROM inventory_balances WHERE inventory_location_id=? AND item_id=? FOR UPDATE');$stmt->execute([$locationId,$itemId]);$row=$stmt->fetch();if($row){$onHand=(float)$row['quantity_on_hand']+$onHandDelta;$allocated=(float)$row['quantity_allocated']+$allocatedDelta;if($onHand<-0.0001||$allocated<-0.0001||$allocated>$onHand+0.0001)throw new RuntimeException('The inventory transaction would create an invalid balance.');$pdo->prepare('UPDATE inventory_balances SET quantity_on_hand=?,quantity_allocated=?,average_unit_cost=CASE WHEN ?>0 THEN ? ELSE average_unit_cost END,updated_at=NOW() WHERE id=?')->execute([$onHand,$allocated,$unitCost,$unitCost,$row['id']]);}else{if($onHandDelta<0||$allocatedDelta<0)throw new RuntimeException('The inventory position does not exist.');$pdo->prepare('INSERT INTO inventory_balances (inventory_location_id,item_id,quantity_on_hand,quantity_allocated,average_unit_cost) VALUES (?,?,?,?,?)')->execute([$locationId,$itemId,$onHandDelta,$allocatedDelta,$unitCost]);}if(function_exists('mysql_repo_clear_cache'))mysql_repo_clear_cache();
}

function inventory_ops_create_reservation(array $record): array
{
    $position=inventory_ops_find_position((int)$record['inventory_location_id'],(int)$record['item_id']);if(!$position||(float)$position['available']+0.0001<(float)$record['quantity'])throw new RuntimeException('Available inventory is insufficient for this reservation.');$record['reservation_number']=$record['reservation_number']??inventory_ops_number('RSV-INV',inventory_ops_reservations());$record['status']='active';$saved=inventory_ops_save_reservation($record);inventory_ops_update_balance((int)$saved['inventory_location_id'],(int)$saved['item_id'],0,(float)$saved['quantity'],(float)$position['unit_cost']);inventory_ops_add_transaction(['id'=>null,'item_id'=>$saved['item_id'],'from_inventory_location_id'=>null,'to_inventory_location_id'=>$saved['inventory_location_id'],'project_workorder_id'=>$saved['project_workorder_id'],'transaction_type'=>'reservation','quantity'=>$saved['quantity'],'unit_cost'=>$position['unit_cost'],'reason_code'=>$saved['reference_type'],'reference_type'=>'inventory_reservation','reference_id'=>$saved['id'],'notes'=>$saved['evidence_note']]);inventory_ops_add_event((int)$saved['company_id'],(int)$saved['inventory_location_id'],(int)$saved['item_id'],'inventory_reservation',(int)$saved['id'],'reserved',null,'active','medium',(float)$saved['quantity'],(float)$saved['quantity']*(float)$position['unit_cost'],$saved['evidence_note']);return $saved;
}

function inventory_ops_release_reservation(array $reservation,string $evidence): array
