    if((string)$reservation['status']!=='active')throw new RuntimeException('Only active reservations can be released.');$position=inventory_ops_find_position((int)$reservation['inventory_location_id'],(int)$reservation['item_id']);$before=$reservation['status'];inventory_ops_update_balance((int)$reservation['inventory_location_id'],(int)$reservation['item_id'],0,-(float)$reservation['quantity'],(float)($position['unit_cost']??0));$reservation['status']='released';$reservation['evidence_note']=mb_substr($evidence,0,5000);$saved=inventory_ops_save_reservation($reservation);inventory_ops_add_transaction(['id'=>null,'item_id'=>$saved['item_id'],'from_inventory_location_id'=>$saved['inventory_location_id'],'to_inventory_location_id'=>null,'project_workorder_id'=>$saved['project_workorder_id'],'transaction_type'=>'release','quantity'=>$saved['quantity'],'unit_cost'=>$position['unit_cost']??0,'reason_code'=>'reservation_release','reference_type'=>'inventory_reservation','reference_id'=>$saved['id'],'notes'=>$evidence]);inventory_ops_add_event((int)$saved['company_id'],(int)$saved['inventory_location_id'],(int)$saved['item_id'],'inventory_reservation',(int)$saved['id'],'released',$before,'released','medium',(float)$saved['quantity'],(float)$saved['quantity']*(float)($position['unit_cost']??0),$evidence);return $saved;
}

function inventory_ops_transfer_effective_status(array $transfer): string
{
    $stored=(string)($transfer['status']??'draft');if(in_array($stored,['in_transit','partially_received','received','canceled'],true))return $stored;$approvalId=(int)($transfer['approval_id']??0);if($approvalId>0){$approval=data_find('workflow_approvals',$approvalId);if($approval&&in_array((string)($approval['status']??''),['pending','in_review','approved','changes_requested','rejected'],true))return (string)$approval['status'];}return $stored;
}

function inventory_ops_submit_transfer(array $transfer): array
{
    if(!in_array(inventory_ops_transfer_effective_status($transfer),['draft','changes_requested'],true))throw new RuntimeException('This transfer is already routed or closed.');if(!inventory_ops_transfer_lines((int)$transfer['id']))throw new RuntimeException('Add at least one transfer line before submission.');$approval=data_upsert('workflow_approvals',['id'=>null,'company_id'=>$transfer['source_company_id'],'module'=>'inventory','entity_type'=>'inventory_transfer_request','entity_id'=>$transfer['id'],'title'=>$transfer['transfer_number'].' · '.data_company_name($transfer['source_company_id']).' to '.data_company_name($transfer['destination_company_id']),'submitted_by'=>(int)current_user()['id'],'assigned_to'=>$transfer['reviewer_id'],'status'=>'pending','submitted_at'=>date('Y-m-d H:i:s'),'due_date'=>date('Y-m-d',strtotime('+2 days')),'notes'=>'Validate source availability, destination need, custody, freight, condition, schedule, reservations, and internal-transfer economics.']);$before=$transfer['status'];$transfer['approval_id']=(int)$approval['id'];$transfer['status']='submitted';$saved=inventory_ops_save_transfer($transfer);inventory_ops_add_transfer_event((int)$saved['id'],'submitted',$before,'submitted','medium','Transfer routed for source and destination approval.');inventory_ops_notify((int)$saved['reviewer_id'],(int)$saved['source_company_id'],'Inventory transfer awaiting approval',$saved['transfer_number'].' requires review.','warning');return $saved;
