function inventory_ops_dispatch_transfer(array $transfer,string $carrier,string $tracking,string $evidence): array
{
    if(inventory_ops_transfer_effective_status($transfer)!=='approved')throw new RuntimeException('The transfer must be approved before dispatch.');$lines=inventory_ops_transfer_lines((int)$transfer['id']);foreach($lines as $line){$position=inventory_ops_find_position((int)$transfer['source_inventory_location_id'],(int)$line['item_id']);$qty=(float)$line['quantity_requested'];if(!$position||(float)$position['available']+0.0001<$qty)throw new RuntimeException('Source inventory is insufficient for '.data_item_name((int)$line['item_id']).'.');}
    foreach($lines as $line){$qty=(float)$line['quantity_requested'];$position=inventory_ops_find_position((int)$transfer['source_inventory_location_id'],(int)$line['item_id']);inventory_ops_update_balance((int)$transfer['source_inventory_location_id'],(int)$line['item_id'],-$qty,0,(float)$line['unit_cost']);$line['quantity_shipped']=$qty;$line['condition_status']='in_transit';inventory_ops_save_transfer_line($line);inventory_ops_add_transaction(['id'=>null,'item_id'=>$line['item_id'],'from_inventory_location_id'=>$transfer['source_inventory_location_id'],'to_inventory_location_id'=>$transfer['destination_inventory_location_id'],'project_workorder_id'=>$transfer['project_workorder_id'],'transaction_type'=>'transfer','quantity'=>$qty,'unit_cost'=>$line['unit_cost'],'reason_code'=>'internal_transfer','reference_type'=>'inventory_transfer_request','reference_id'=>$transfer['id'],'notes'=>$evidence]);inventory_ops_add_event((int)$transfer['source_company_id'],(int)$transfer['source_inventory_location_id'],(int)$line['item_id'],'inventory_transfer_request',(int)$transfer['id'],'dispatched','approved','in_transit','medium',$qty,$qty*(float)$line['unit_cost'],$evidence);}
    $before=$transfer['status'];$transfer['status']='in_transit';$transfer['shipped_at']=date('Y-m-d H:i:s');$transfer['carrier']=mb_substr($carrier,0,160);$transfer['tracking_number']=mb_substr($tracking,0,160);$transfer['evidence_note']=mb_substr($evidence,0,5000);$saved=inventory_ops_save_transfer($transfer);inventory_ops_add_transfer_event((int)$saved['id'],'dispatched',$before,'in_transit','medium',$evidence);return $saved;
