function inventory_ops_receive_transfer(array $transfer,string $evidence): array
{
    if(!in_array((string)$transfer['status'],['in_transit','partially_received'],true))throw new RuntimeException('Only an in-transit transfer can be received.');$all=true;foreach(inventory_ops_transfer_lines((int)$transfer['id']) as $line){$remaining=max(0,(float)$line['quantity_shipped']-(float)$line['quantity_received']);if($remaining<=0)continue;inventory_ops_update_balance((int)$transfer['destination_inventory_location_id'],(int)$line['item_id'],$remaining,0,(float)$line['unit_cost']);$line['quantity_received']=(float)$line['quantity_received']+$remaining;$line['condition_status']='accepted';$line['notes']=mb_substr($evidence,0,5000);inventory_ops_save_transfer_line($line);inventory_ops_add_event((int)$transfer['destination_company_id'],(int)$transfer['destination_inventory_location_id'],(int)$line['item_id'],'inventory_transfer_request',(int)$transfer['id'],'received','in_transit','received','medium',$remaining,$remaining*(float)$line['unit_cost'],$evidence);if((float)$line['quantity_received']+0.0001<(float)$line['quantity_shipped'])$all=false;}$before=$transfer['status'];$transfer['status']=$all?'received':'partially_received';$transfer['received_at']=$all?date('Y-m-d H:i:s'):null;$transfer['evidence_note']=mb_substr($evidence,0,5000);$saved=inventory_ops_save_transfer($transfer);inventory_ops_add_transfer_event((int)$saved['id'],'received',$before,$saved['status'],'medium',$evidence);return $saved;
